//! Signatures converted from the Detect It Easy (DIE) database, bundled as data.
//!
//! `data/die-signatures.json` is generated by `tools/die_signatures.py` from DIE's `db/` scripts at a pinned
//! commit (recorded in the file). DIE is MIT-licensed, Copyright (c) 2012-2026 hors and the DIE contributors;
//! THIRD-PARTY-NOTICES carries the licence. Each converted signature keeps DIE's detection type, name and version
//! strings, the script it came from and that script's authors, and is marked [`Source::DetectItEasy`], so its
//! matches are told apart from this crate's own rules.
//!
//! The converter only emits conditions rampage-detect tests exactly as DIE does (entry-point patterns, following
//! relative jumps where DIE's `$` does; bytes at a file offset or the start of the overlay; section names; linked
//! libraries; imported functions; exports; overlay presence; pointer width), so a converted signature is never
//! broader than DIE's own test. Scripts that need anything else are skipped and counted in the converter's report.

use std::sync::OnceLock;

use rampage_loaders::Format;
use serde::Deserialize;
use serde_json::Value;

use crate::model::{Condition, Kind, Signature, Source};
use crate::pattern::{BytePattern, JumpPattern};

const DATA: &str = include_str!("../data/die-signatures.json");

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct File {
    source: String,
    url: String,
    commit: String,
    license: String,
    copyright: String,
    signatures: Vec<Entry>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Entry {
    kind: String,
    die_type: String,
    name: String,
    #[serde(default)]
    version: Option<String>,
    #[serde(default)]
    options: Option<String>,
    format: String,
    file: String,
    #[serde(default)]
    authors: Option<String>,
    conditions: Vec<Value>,
}

/// The converted signatures. The data is a crate constant checked by the tests, so a malformed entry is a bug in
/// the generated file and panics rather than being skipped silently.
pub(crate) fn signatures() -> Vec<Signature> {
    static PARSED: OnceLock<Vec<Signature>> = OnceLock::new();
    PARSED.get_or_init(|| parse(DATA).expect("bundled Detect It Easy signatures parse").0).clone()
}

pub(crate) fn parse(text: &str) -> Result<(Vec<Signature>, String), String> {
    let file: File = serde_json::from_str(text).map_err(|error| format!("invalid JSON: {error}"))?;
    if file.source != "Detect It Easy" || file.license != "MIT" || file.url.is_empty() || file.copyright.is_empty() {
        return Err("missing provenance".to_owned());
    }
    let signatures = file
        .signatures
        .into_iter()
        .map(|entry| {
            let file = entry.file.clone();
            signature(entry).map_err(|error| format!("{file}: {error}"))
        })
        .collect::<Result<_, _>>()?;
    Ok((signatures, file.commit))
}

fn signature(entry: Entry) -> Result<Signature, String> {
    let kind = match entry.kind.as_str() {
        "packer" => Kind::Packer,
        "protector" => Kind::Protector,
        "cryptor" => Kind::Cryptor,
        "compiler" => Kind::Compiler,
        "linker" => Kind::Linker,
        "installer" => Kind::Installer,
        "sfx" => Kind::Sfx,
        "joiner" => Kind::Joiner,
        other => return Err(format!("unknown kind {other}")),
    };
    let format = match entry.format.as_str() {
        "pe" => Format::Pe,
        "elf" => Format::Elf,
        "macho" => Format::MachO,
        other => return Err(format!("unknown format {other}")),
    };
    if entry.conditions.is_empty() {
        return Err("no conditions".to_owned());
    }
    let mut conditions = vec![Condition::Format(format)];
    for value in &entry.conditions {
        conditions.push(condition(value)?);
    }
    let version = match (entry.version.filter(|v| !v.is_empty()), entry.options.filter(|o| !o.is_empty())) {
        (Some(version), Some(options)) => Some(format!("{version} ({options})")),
        (version, options) => version.or(options),
    };
    let origin = match &entry.authors {
        Some(authors) => format!("Detect It Easy {} (by {authors})", entry.file),
        None => format!("Detect It Easy {}", entry.file),
    };
    let mut signature = Signature::new(&entry.name, kind, conditions)
        .with_note(&format!("Detect It Easy {} rule {}", entry.die_type, entry.file));
    signature.version = version;
    signature.source = Source::DetectItEasy;
    signature.origin = Some(origin);
    Ok(signature)
}

fn condition(value: &Value) -> Result<Condition, String> {
    let object = value.as_object().ok_or("condition is not an object")?;
    let text = |key: &str| -> Result<String, String> {
        object.get(key).and_then(Value::as_str).map(str::to_owned).ok_or_else(|| format!("{key} is not a string"))
    };
    let pattern = |key: &str| -> Result<BytePattern, String> {
        BytePattern::parse(&text(key)?).map_err(|error| format!("{key}: {error}"))
    };
    let keys: Vec<&str> = object.keys().map(String::as_str).collect();
    Ok(match keys.as_slice() {
        ["entry"] => match JumpPattern::parse(&text("entry")?).map_err(|error| format!("entry: {error}"))?.into_plain() {
            Ok(pattern) => Condition::Entry { pattern, ep_only: true },
            Err(jumps) => Condition::EntryJumps(jumps),
        },
        ["file_bytes", "offset"] => Condition::FileBytes {
            offset: object["offset"].as_u64().ok_or("offset is not a number")?,
            pattern: pattern("file_bytes")?,
        },
        ["overlay_bytes"] => Condition::OverlayBytes(pattern("overlay_bytes")?),
        ["overlay"] if object["overlay"] == Value::Bool(true) => Condition::OverlayPresent,
        ["section"] => Condition::SectionName(text("section")?),
        ["library"] => Condition::Library(text("library")?),
        ["import"] => Condition::ImportedFunction { library: None, name: text("import")? },
        ["from", "import"] => Condition::ImportedFunction { library: Some(text("from")?), name: text("import")? },
        ["export"] => Condition::Export(text("export")?),
        ["bits"] => match object["bits"].as_u64() {
            Some(32) => Condition::PointerBits(32),
            Some(64) => Condition::PointerBits(64),
            _ => return Err("bits is not 32 or 64".to_owned()),
        },
        _ => return Err(format!("unknown condition {value}")),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_data_parses_with_provenance() {
        let (signatures, commit) = parse(DATA).unwrap();
        assert!(signatures.len() > 300, "{}", signatures.len());
        assert_eq!(commit.len(), 40);
        for signature in &signatures {
            assert_eq!(signature.source, Source::DetectItEasy);
            assert!(signature.origin.as_deref().is_some_and(|origin| origin.starts_with("Detect It Easy ")));
            assert!(matches!(signature.conditions[0], Condition::Format(_)), "{}", signature.name);
            assert!(signature.conditions.len() >= 2, "{}", signature.name);
        }
    }

    #[test]
    fn malformed_entries_are_rejected() {
        let wrap = |entry: &str| {
            format!(
                r#"{{"source":"Detect It Easy","url":"u","commit":"c","license":"MIT","copyright":"c","signatures":[{entry}]}}"#
            )
        };
        let entry = |conditions: &str| {
            wrap(&format!(
                r#"{{"kind":"packer","die_type":"packer","name":"X","format":"pe","file":"PE/x.sg","conditions":{conditions}}}"#
            ))
        };
        assert!(parse(&entry(r#"[{"entry":"60 E8 ?? ?? ?? ??"}]"#)).is_ok());
        assert!(parse(&entry(r#"[{"entry":"E9 $4 60 BE"}]"#)).is_ok());
        assert!(parse(&entry("[]")).is_err());
        assert!(parse(&entry(r#"[{"entry":"6"}]"#)).is_err());
        assert!(parse(&entry(r#"[{"regex":"x"}]"#)).is_err());
        assert!(parse(&entry(r#"[{"section":"a","library":"b"}]"#)).is_err());
        assert!(parse(&entry(r#"[{"bits":16}]"#)).is_err());
        assert!(parse(&wrap(r#"{"kind":"library","die_type":"library","name":"X","format":"pe","file":"f","conditions":[{"section":"a"}]}"#)).is_err());
    }
}
